type Skill = { name: string; level: number };
type StudentProfile = { name: string; college: string; degree: string; branch: string; studyYear: string; graduationYear: string; experience: string; skills: Skill[]; interests: string[]; targetCareer: string; projects: string[] };
type Career = { id: string; title: string; family: string; description: string; requirements: string[]; sequence: string[]; projects: string[]; accent: string };
type Gap = { name: string; priority: "High" | "Medium" | "Low"; current: number; required: number; why: string; time: string };
type Project = { id: string; title: string; difficulty: "Starter" | "Intermediate" | "Stretch"; time: string; skills: string[]; description: string; rationale: string; technologies: string[]; status: "Not started" | "In progress" | "Complete" };
type Task = { id: string; day: string; title: string; description: string; complete: boolean };
type Stage = { id: string; title: string; duration: string; skills: string[]; objectives: string[]; projects: string[]; complete: boolean };
type Store = { profile: StudentProfile; completedTasks: string[]; projectStatus: Record<string, Project["status"]>; completedStages: string[]; theme: "light" | "dark"; notifications: boolean };

